/**
 * Design-set engine.
 *
 * A design-set is a folder under the design-sets directory:
 *
 *   <name>/set.json       metadata, settings, images, tags (schema below)
 *   <name>/custom.less    -> setting custom_less          (optional)
 *   <name>/header.html    -> setting custom_header        (optional)
 *   <name>/footer.html    -> setting custom_footer        (optional)
 *   <name>/static/…       fonts/images copied to public/assets/<subdir>/<name>/
 *   <name>/images/…       logo / dark logo / email logo / favicon sources
 *   <name>/screenshots/   generated by preview/screenshot
 *
 * Semantics (deterministic switching):
 *   - THEME_KEYS are fully defined by a set: an omitted theme key is returned
 *     to Flarum's default on apply.
 *   - optional design keys and extension keys are only written when listed.
 *   - images: omitted = keep, null = remove, "images/x.png" = upload.
 *   - tags: only the listed slugs/fields are changed.
 *   - "@@ASSET:path@@" in LESS/HTML/settings becomes a versioned URL of the
 *     copied static file (nginx caches /assets fonts for 30 days).
 *
 * Every live write is preceded by a snapshot; apply rolls back automatically
 * if any step fails, and rollback restores absent/null/value states exactly.
 */

import { createHash } from "node:crypto";
import {
  copyFileSync,
  cpSync,
  existsSync,
  mkdirSync,
  readdirSync,
  readFileSync,
  rmSync,
  statSync,
  writeFileSync,
} from "node:fs";
import { basename, dirname, extname, join, relative, resolve, sep } from "node:path";
import { spawn } from "node:child_process";
import { z } from "zod";
import { packageRoot } from "./config.js";
import { requireAdmin } from "./auth.js";
import { Ops, OpsError, describeFailure, preview, summarise, type StepResult } from "./ops.js";
import {
  CSS_KEYS,
  IMAGE_KINDS,
  NEEDS_CACHE_CLEAR_KEYS,
  OPTIONAL_DESIGN_KEYS,
  THEME_KEYS,
  checkSettingsWrite,
  classifyKey,
  extensionPrefixOf,
  lintLess,
  normaliseValue,
  type ImageKind,
  type ValidationIssue,
} from "./policy.js";
import { valueOf, type SettingState, type SettingsMap } from "./local.js";
import { checkUpload } from "./images.js";

// ------------------------------------------------------------------ schema

const NAME = /^[a-z0-9]+(-[a-z0-9]+)*$/;
const HEX = /^#([0-9a-f]{3}|[0-9a-f]{6})$/i;

export const SetSchema = z
  .object({
    name: z.string().regex(NAME, "kebab-case: lowercase letters, digits, single hyphens"),
    title: z.string().min(1),
    description: z.string().optional(),
    flarum: z.string().optional(),
    requires_extensions: z.array(z.string().regex(/^[a-z0-9][a-z0-9-]*$/)).optional(),
    settings: z.record(z.string(), z.union([z.string(), z.number(), z.boolean(), z.null()])).optional(),
    less: z.string().optional(),
    header: z.string().optional(),
    footer: z.string().optional(),
    static: z.string().optional(),
    images: z
      .object({
        logo: z.string().nullable().optional(),
        logo_dark_mode: z.string().nullable().optional(),
        email_logo: z.string().nullable().optional(),
        favicon: z.string().nullable().optional(),
      })
      .strict()
      .optional(),
    tags: z
      .record(
        z.string(),
        z
          .object({
            color: z.string().regex(HEX).nullable().optional(),
            icon: z.string().nullable().optional(),
            description: z.string().max(700).nullable().optional(),
          })
          .strict(),
      )
      .optional(),
  })
  .strict();

export type DesignSet = z.infer<typeof SetSchema>;

const STATIC_EXT = new Set([".woff2", ".woff", ".ttf", ".otf", ".png", ".jpg", ".jpeg", ".webp", ".gif", ".svg", ".avif", ".ico"]);
const MANAGED_SETTING_FILES = { less: "custom_less", header: "custom_header", footer: "custom_footer" } as const;

/** Flarum defaults used when a set omits a CSS-relevant theme key (POSTing triggers the rebuild). */
const CSS_DEFAULTS: Record<string, string> = {
  custom_less: "",
  theme_primary_color: "#4D698E",
  theme_secondary_color: "#4D698E",
};

/** Keys never compared/restored: managed by Flarum or by the upload endpoints. */
const VOLATILE = [/^assets_dirty\./, /^custom_less_error$/, /_path$/, /_size$/, /^logo_email_copy_/];

// ------------------------------------------------------------- snapshots

export interface Snapshot {
  id: string;
  createdAt: string;
  reason: string;
  forum: string;
  settingKeys: string[];
  settings: SettingsMap;
  images: Record<ImageKind, { file: string | null; path: string | null; sha256?: string }>;
  tags: Record<string, { id: string; color: string | null; icon: string | null; description: string | null }>;
  marker: AppliedMarker | null;
}

export interface AppliedMarker {
  set: string;
  appliedAt: string;
  snapshot: string;
  setHash: string;
  expected: Record<string, string | null | "__default__">;
  imageHashes: Partial<Record<ImageKind, string>>;
}

interface PlannedSettings {
  post: Record<string, string | null>;
  reset: string[];
  issues: ValidationIssue[];
}

interface Plan {
  set: string;
  settings: { key: string; from: string; to: string; action: "set" | "reset" }[];
  images: { kind: ImageKind; action: "upload" | "delete" | "keep"; file?: string }[];
  tags: { slug: string; id?: string; changes: Record<string, { from: unknown; to: unknown }> }[];
  static: { files: number; target: string };
  needsCacheClear: boolean;
  issues: ValidationIssue[];
  blocked: boolean;
}

function sha256(buf: Uint8Array | string): string {
  return createHash("sha256").update(buf).digest("hex");
}

function nowId(): string {
  return new Date().toISOString().replace(/[-:]/g, "").replace(/\.\d+Z$/, "Z");
}

function isVolatile(key: string): boolean {
  return VOLATILE.some((r) => r.test(key));
}

function sameState(a: SettingState | undefined, b: SettingState | undefined): boolean {
  const sa = a ?? { state: "absent" };
  const sb = b ?? { state: "absent" };
  if (sa.state !== sb.state) return false;
  return sa.state !== "value" || (sb.state === "value" && sa.value === sb.value);
}

// ------------------------------------------------------------------ engine

export class DesignSets {
  constructor(readonly ops: Ops) {}

  get dir(): string {
    return this.ops.cfg.designSetsDir;
  }

  get snapshotsDir(): string {
    return join(this.dir, "_snapshots");
  }

  private get markerFile(): string {
    return join(this.dir, ".applied.json");
  }

  private get lockFile(): string {
    return join(this.dir, ".lock");
  }

  private forumRoot(): string {
    if (!this.ops.cfg.forumRoot) throw new Error("design-set operations need forum_root (local install) in forum.json");
    return this.ops.cfg.forumRoot;
  }

  setDir(name: string): string {
    if (!NAME.test(name)) throw new Error(`invalid design-set name "${name}"`);
    return join(this.dir, name);
  }

  // ---------------------------------------------------------------- list

  list(): Record<string, unknown>[] {
    if (!existsSync(this.dir)) return [];
    const marker = this.marker();
    return readdirSync(this.dir, { withFileTypes: true })
      .filter((d) => d.isDirectory() && !d.name.startsWith("_") && !d.name.startsWith("."))
      .map((d) => {
        const file = join(this.dir, d.name, "set.json");
        if (!existsSync(file)) return { name: d.name, error: "missing set.json" };
        try {
          const set = this.load(d.name);
          const shots = join(this.dir, d.name, "screenshots");
          return {
            name: set.name,
            title: set.title,
            description: set.description,
            colors: { primary: set.settings?.theme_primary_color, secondary: set.settings?.theme_secondary_color, scheme: set.settings?.color_scheme },
            screenshots: existsSync(shots) ? readdirSync(shots).filter((f) => f.endsWith(".png")).length : 0,
            applied: marker?.set === set.name,
          };
        } catch (e) {
          return { name: d.name, error: (e as Error).message };
        }
      });
  }

  load(name: string): DesignSet {
    const dir = this.setDir(name);
    const file = join(dir, "set.json");
    if (!existsSync(file)) throw new Error(`design-set "${name}" not found (${file})`);
    let raw: unknown;
    try {
      raw = JSON.parse(readFileSync(file, "utf8"));
    } catch (e) {
      throw new Error(`${file}: invalid JSON (${(e as Error).message})`);
    }
    const parsed = SetSchema.safeParse(raw);
    if (!parsed.success) {
      throw new Error(`${file}: ${parsed.error.issues.map((i) => `${i.path.join(".") || "(root)"}: ${i.message}`).join("; ")}`);
    }
    if (parsed.data.name !== name) throw new Error(`${file}: "name" is "${parsed.data.name}" but the folder is "${name}"`);
    return parsed.data;
  }

  marker(): AppliedMarker | null {
    if (!existsSync(this.markerFile)) return null;
    try {
      return JSON.parse(readFileSync(this.markerFile, "utf8")) as AppliedMarker;
    } catch {
      return null;
    }
  }

  private writeMarker(m: AppliedMarker | null): void {
    if (m) writeFileSync(this.markerFile, JSON.stringify(m, null, 2) + "\n");
    else if (existsSync(this.markerFile)) rmSync(this.markerFile);
  }

  /** Hash of everything that defines a set (used for drift / "already applied"). */
  setHash(name: string): string {
    const dir = this.setDir(name);
    const h = createHash("sha256");
    const walk = (d: string) => {
      for (const e of readdirSync(d, { withFileTypes: true }).sort((a, b) => a.name.localeCompare(b.name))) {
        if (e.name === "screenshots") continue;
        const p = join(d, e.name);
        if (e.isDirectory()) walk(p);
        else {
          h.update(relative(dir, p));
          h.update(readFileSync(p));
        }
      }
    };
    walk(dir);
    return h.digest("hex").slice(0, 16);
  }

  // ------------------------------------------------------------- locking

  private lock<T>(fn: () => Promise<T>): Promise<T> {
    mkdirSync(this.dir, { recursive: true });
    if (existsSync(this.lockFile)) {
      const info = readFileSync(this.lockFile, "utf8").trim();
      const pid = Number(info.split(" ")[0]);
      let alive = false;
      try {
        if (pid) {
          process.kill(pid, 0);
          alive = true;
        }
      } catch {
        alive = false;
      }
      if (alive && pid !== process.pid) {
        return Promise.reject(new Error(`another design-set write is running (lock ${this.lockFile}: ${info}); wait for it to finish`));
      }
    }
    writeFileSync(this.lockFile, `${process.pid} ${new Date().toISOString()}\n`);
    return fn().finally(() => {
      try {
        rmSync(this.lockFile);
      } catch {
        /* ignore */
      }
    });
  }

  // ----------------------------------------------------- live state read

  /** Keys captured by snapshots: theme + optional design keys + all enabled-extension settings. */
  private async snapshotKeySpec(): Promise<{ keys: string[]; prefixes: string[] }> {
    const ext = await this.ops.enabledExtensions();
    const prefixes = ext.flatMap((id) => [`${id}.`, ...(id.startsWith("flarum-") ? [`${id.slice(7)}.`] : [])]);
    const imageKeys = Object.values(IMAGE_KINDS).map((s) => s.pathKey);
    return { keys: [...THEME_KEYS, ...OPTIONAL_DESIGN_KEYS, ...imageKeys], prefixes };
  }

  private async readTags(): Promise<Snapshot["tags"]> {
    const ext = await this.ops.enabledExtensions();
    if (!ext.includes("flarum-tags")) return {};
    const doc = await this.ops.client.request<{ data?: { id: string; attributes: Record<string, unknown> }[] }>({ path: "/tags" });
    const out: Snapshot["tags"] = {};
    for (const t of doc.data ?? []) {
      const a = t.attributes;
      out[String(a.slug)] = {
        id: String(t.id),
        // Keep null and "" distinct: both are valid, different stored values.
        color: (a.color as string | null | undefined) ?? null,
        icon: (a.icon as string | null | undefined) ?? null,
        description: (a.description as string | null | undefined) ?? null,
      };
    }
    return out;
  }

  async snapshot(reason: string): Promise<Snapshot> {
    const root = this.forumRoot();
    const spec = await this.snapshotKeySpec();
    const settings = await this.ops.db.read(spec.keys, spec.prefixes);
    const id = `${nowId()}-${reason.replace(/[^a-z0-9-]+/gi, "-").slice(0, 40)}`;
    const dir = join(this.snapshotsDir, id);
    mkdirSync(dir, { recursive: true });
    const images = {} as Snapshot["images"];
    for (const [kind, s] of Object.entries(IMAGE_KINDS) as [ImageKind, (typeof IMAGE_KINDS)[ImageKind]][]) {
      const path = valueOf(settings, s.pathKey) ?? null;
      const src = path ? join(root, "public", "assets", path) : null;
      if (path && src && existsSync(src)) {
        const file = `${kind}${extname(path)}`;
        copyFileSync(src, join(dir, file));
        images[kind] = { file, path, sha256: sha256(readFileSync(src)) };
      } else {
        images[kind] = { file: null, path };
      }
    }
    const snap: Snapshot = {
      id,
      createdAt: new Date().toISOString(),
      reason,
      forum: this.ops.client.forumUrl,
      settingKeys: Object.keys(settings),
      settings,
      images,
      tags: await this.readTags(),
      marker: this.marker(),
    };
    writeFileSync(join(dir, "snapshot.json"), JSON.stringify(snap, null, 2) + "\n");
    return snap;
  }

  listSnapshots(): { id: string; createdAt?: string; reason?: string }[] {
    if (!existsSync(this.snapshotsDir)) return [];
    return readdirSync(this.snapshotsDir)
      .filter((d) => existsSync(join(this.snapshotsDir, d, "snapshot.json")))
      .sort()
      .reverse()
      .map((id) => {
        try {
          const s = JSON.parse(readFileSync(join(this.snapshotsDir, id, "snapshot.json"), "utf8")) as Snapshot;
          return { id, createdAt: s.createdAt, reason: s.reason };
        } catch {
          return { id };
        }
      });
  }

  loadSnapshot(id?: string): Snapshot {
    const target = id ?? this.listSnapshots()[0]?.id;
    if (!target) throw new Error("no snapshots exist yet");
    if (!/^[\w.-]+$/.test(target)) throw new Error(`invalid snapshot id "${target}"`);
    const file = join(this.snapshotsDir, target, "snapshot.json");
    if (!existsSync(file)) throw new Error(`snapshot "${target}" not found`);
    return JSON.parse(readFileSync(file, "utf8")) as Snapshot;
  }

  // --------------------------------------------------------- resolution

  private assetsUrlPath(forum: Record<string, unknown>): string {
    const base = String(forum.assetsBaseUrl ?? `${this.ops.client.forumUrl}/assets`);
    try {
      return new URL(base).pathname.replace(/\/+$/, "");
    } catch {
      return "/assets";
    }
  }

  private staticFiles(set: DesignSet): { abs: string; rel: string }[] {
    const dir = join(this.setDir(set.name), set.static ?? "static");
    if (!existsSync(dir)) return [];
    const out: { abs: string; rel: string }[] = [];
    const walk = (d: string) => {
      for (const e of readdirSync(d, { withFileTypes: true })) {
        if (e.name.startsWith(".")) continue;
        const p = join(d, e.name);
        if (e.isDirectory()) walk(p);
        else out.push({ abs: p, rel: relative(dir, p).split(sep).join("/") });
      }
    };
    walk(dir);
    return out;
  }

  private resolveAssets(set: DesignSet, text: string, assetsUrlPath: string, issues: ValidationIssue[], key: string): string {
    const files = new Map(this.staticFiles(set).map((f) => [f.rel, f.abs]));
    // Placeholders inside comments (LESS /* */ and //, HTML <!-- -->) are left alone and never reported.
    const comments: [number, number][] = [];
    for (const m of text.matchAll(/\/\*[\s\S]*?\*\/|<!--[\s\S]*?-->|(?:^|(?<=[\s;{}]))\/\/[^\n]*/g)) {
      comments.push([m.index!, m.index! + m[0].length]);
    }
    const inComment = (i: number) => comments.some(([a, b]) => i >= a && i < b);
    return text.replace(/@@ASSET:([^@\s]+)@@/g, (match, rel: string, offset: number) => {
      if (inComment(offset)) return match;
      const abs = files.get(rel);
      if (!abs) {
        issues.push({ key, level: "error", message: `@@ASSET:${rel}@@ refers to a file that is not in ${set.static ?? "static"}/` });
        return rel;
      }
      const v = sha256(readFileSync(abs)).slice(0, 8);
      return `${assetsUrlPath}/${this.ops.cfg.publicAssetsSubdir}/${set.name}/${rel}?v=${v}`;
    });
  }

  /** Desired settings of a set (files resolved), split into posts and resets. */
  private async plannedSettings(set: DesignSet, current: SettingsMap, forum: Record<string, unknown>): Promise<PlannedSettings> {
    const issues: ValidationIssue[] = [];
    const assets = this.assetsUrlPath(forum);
    const desired: Record<string, unknown> = { ...(set.settings ?? {}) };
    for (const [field, key] of Object.entries(MANAGED_SETTING_FILES) as [keyof typeof MANAGED_SETTING_FILES, string][]) {
      const file = set[field];
      if (!file) continue;
      if (key in desired) issues.push({ key, level: "error", message: `set both in settings and via "${field}": ${file}` });
      const p = resolve(this.setDir(set.name), file);
      if (!p.startsWith(this.setDir(set.name) + sep) || !existsSync(p)) {
        issues.push({ key, level: "error", message: `file ${file} not found inside the set` });
        continue;
      }
      desired[key] = readFileSync(p, "utf8");
    }
    for (const [k, v] of Object.entries(desired)) {
      if (typeof v === "string") desired[k] = this.resolveAssets(set, v, assets, issues, k);
    }

    const ext = await this.ops.enabledExtensions();
    const required = set.requires_extensions ?? [];
    for (const id of required) {
      if (!ext.includes(id)) issues.push({ key: id, level: "error", message: `requires extension ${id}, which is not enabled (enable it separately, with approval)` });
    }
    for (const k of Object.keys(desired)) {
      const cls = classifyKey(k, ext);
      if (cls === "extension") {
        const id = extensionPrefixOf(k, ext)!;
        if (!required.includes(id)) issues.push({ key: k, level: "error", message: `extension key: add "${id}" to requires_extensions` });
      } else if (cls === "other") {
        issues.push({ key: k, level: "error", message: "not a design key and not prefixed by an enabled extension id" });
      }
    }
    const checked = checkSettingsWrite(desired, { enabledExtensions: ext, allowProtected: false, allowOther: false });
    issues.push(...checked.issues.filter((i) => !issues.some((j) => j.key === i.key && j.message === i.message)));

    const post: Record<string, string | null> = {};
    const reset: string[] = [];
    for (const [k, v] of Object.entries(checked.normalised)) {
      if (!sameState(current[k], v === null ? { state: "null" } : { state: "value", value: v })) post[k] = v;
    }
    for (const k of THEME_KEYS) {
      if (k in checked.normalised) continue;
      if (k in CSS_DEFAULTS) {
        if (!sameState(current[k], { state: "value", value: CSS_DEFAULTS[k] }) && current[k]?.state !== "absent") post[k] = CSS_DEFAULTS[k];
      } else if (current[k] && current[k].state !== "absent") {
        reset.push(k);
      }
    }
    if (desired.color_scheme !== undefined && desired.color_scheme !== "auto" && desired.show_theme_selector !== undefined) {
      issues.push({ key: "show_theme_selector", level: "warning", message: "only has an effect when color_scheme is auto" });
    }
    if (typeof desired.custom_less === "string" && /@body-bg-dark\s*:/.test(desired.custom_less) && !/data-theme\^=dark\]\s*body\b/.test(desired.custom_less)) {
      issues.push({
        key: "custom_less",
        level: "warning",
        message:
          "redefines @body-bg-dark, but Flarum's inline critical CSS `[data-theme^=dark] body{background:…}` (derived from theme_secondary_color) wins over core's body rule; add `html[data-theme^=dark] body { background: var(--body-bg); }`",
      });
    }
    if (typeof desired.custom_less === "string" && desired.color_scheme !== "light" && desired.color_scheme !== "dark") {
      const less = desired.custom_less;
      if (/data-theme\^?=\s*["']?dark/.test(less) && !/-hc/.test(less)) {
        issues.push({ key: "custom_less", level: "warning", message: "styles dark/light but never mentions the -hc (high contrast) schemes; core re-overrides some variables there, check light-hc/dark-hc screenshots" });
      }
    }
    return { post, reset, issues };
  }

  // -------------------------------------------------------------- validate

  async validate(name: string): Promise<{ ok: boolean; issues: ValidationIssue[] }> {
    const issues: ValidationIssue[] = [];
    let set: DesignSet;
    try {
      set = this.load(name);
    } catch (e) {
      return { ok: false, issues: [{ key: "set.json", level: "error", message: (e as Error).message }] };
    }
    const dir = this.setDir(name);
    for (const f of this.staticFiles(set)) {
      if (!STATIC_EXT.has(extname(f.rel).toLowerCase())) {
        issues.push({ key: `static/${f.rel}`, level: "error", message: `file type not allowed in public assets (allowed: ${[...STATIC_EXT].join(" ")}); never place .php there` });
      }
      if (statSync(f.abs).size > 5 * 1024 * 1024) issues.push({ key: `static/${f.rel}`, level: "warning", message: "larger than 5 MB" });
    }
    for (const [kind, file] of Object.entries(set.images ?? {}) as [ImageKind, string | null][]) {
      if (!file) continue;
      const p = resolve(dir, file);
      if (!p.startsWith(dir + sep) || !existsSync(p)) {
        issues.push({ key: `images.${kind}`, level: "error", message: `${file} not found inside the set` });
        continue;
      }
      try {
        checkUpload(readFileSync(p), file);
      } catch (e) {
        issues.push({ key: `images.${kind}`, level: "error", message: (e as Error).message });
      }
    }
    if (set.images?.logo_dark_mode && set.images.logo === undefined && this.ops.local) {
      const normal = valueOf(await this.ops.db.read(["logo_path"]), "logo_path");
      if (!normal) issues.push({ key: "images.logo_dark_mode", level: "warning", message: "no normal logo is live and the set adds none: Flarum only renders the dark-mode logo when a normal logo exists" });
    }
    if (set.images?.logo_dark_mode && set.images.logo === null) {
      issues.push({ key: "images.logo_dark_mode", level: "warning", message: "the set removes the normal logo, so the dark-mode logo will not be shown (Flarum renders it only alongside a normal logo)" });
    }
    if (this.ops.local) {
      const current = await this.ops.db.read([...THEME_KEYS, ...Object.keys(set.settings ?? {})]);
      const forum = (await this.ops.whoami()).forum;
      issues.push(...(await this.plannedSettings(set, current, forum)).issues);
      if (set.tags && Object.keys(set.tags).length) {
        const live = await this.readTags();
        for (const slug of Object.keys(set.tags)) {
          if (!live[slug]) issues.push({ key: `tags.${slug}`, level: "error", message: `no tag with slug "${slug}" (existing: ${Object.keys(live).join(", ") || "none"})` });
        }
      }
    } else {
      for (const field of ["less"] as const) {
        const f = set[field];
        if (f && existsSync(join(dir, f))) issues.push(...lintLess(readFileSync(join(dir, f), "utf8")));
      }
    }
    return { ok: !issues.some((i) => i.level === "error"), issues };
  }

  // ------------------------------------------------------------------ diff

  async plan(name: string): Promise<Plan> {
    const set = this.load(name);
    const root = this.forumRoot();
    const validation = await this.validate(name);
    const spec = await this.snapshotKeySpec();
    const current = await this.ops.db.read([...spec.keys, ...Object.keys(set.settings ?? {})], spec.prefixes);
    const forum = (await this.ops.whoami()).forum;
    const planned = await this.plannedSettings(set, current, forum);
    const marker = this.marker();

    const settings: Plan["settings"] = [
      ...Object.entries(planned.post).map(([k, v]) => ({ key: k, from: summarise(current[k]), to: preview(v), action: "set" as const })),
      ...planned.reset.map((k) => ({ key: k, from: summarise(current[k]), to: "(Flarum default)", action: "reset" as const })),
    ];

    const images: Plan["images"] = [];
    for (const kind of Object.keys(IMAGE_KINDS) as ImageKind[]) {
      const want = set.images?.[kind];
      const livePath = valueOf(current, IMAGE_KINDS[kind].pathKey);
      if (want === undefined) images.push({ kind, action: "keep" });
      else if (want === null) images.push({ kind, action: livePath ? "delete" : "keep" });
      else {
        const hash = sha256(readFileSync(join(this.setDir(name), want)));
        const unchanged = marker?.set === name && marker.imageHashes?.[kind] === hash && Boolean(livePath);
        images.push({ kind, action: unchanged ? "keep" : "upload", file: want });
      }
    }

    const tags: Plan["tags"] = [];
    if (set.tags && Object.keys(set.tags).length) {
      const live = await this.readTags();
      for (const [slug, want] of Object.entries(set.tags)) {
        const t = live[slug];
        const changes: Record<string, { from: unknown; to: unknown }> = {};
        for (const f of ["color", "icon", "description"] as const) {
          if (want[f] === undefined) continue;
          if ((t?.[f] ?? null) !== (want[f] ?? null)) changes[f] = { from: t?.[f] ?? null, to: want[f] ?? null };
        }
        if (Object.keys(changes).length) tags.push({ slug, id: t?.id, changes });
      }
    }

    const files = this.staticFiles(set);
    const issues = [...validation.issues, ...planned.issues.filter((i) => !validation.issues.some((j) => j.key === i.key && j.message === i.message))];
    return {
      set: name,
      settings,
      images,
      tags,
      static: { files: files.length, target: join(root, "public", "assets", this.ops.cfg.publicAssetsSubdir, name) },
      needsCacheClear: planned.reset.some((k) => CSS_KEYS.includes(k)) || Object.keys(planned.post).some((k) => NEEDS_CACHE_CLEAR_KEYS.includes(k)),
      issues,
      blocked: issues.some((i) => i.level === "error"),
    };
  }

  // ----------------------------------------------------------------- apply

  private syncStatic(set: DesignSet): StepResult {
    const files = this.staticFiles(set);
    const target = join(this.forumRoot(), "public", "assets", this.ops.cfg.publicAssetsSubdir, set.name);
    if (!files.length) {
      return { step: "static files", ok: true, detail: "none" };
    }
    mkdirSync(target, { recursive: true });
    const keep = new Set<string>();
    for (const f of files) {
      const dest = join(target, f.rel);
      mkdirSync(dirname(dest), { recursive: true });
      copyFileSync(f.abs, dest);
      keep.add(dest);
    }
    // Remove stale files of this set only.
    const prune = (d: string) => {
      for (const e of readdirSync(d, { withFileTypes: true })) {
        const p = join(d, e.name);
        if (e.isDirectory()) prune(p);
        else if (!keep.has(p)) rmSync(p);
      }
    };
    prune(target);
    return { step: "static files", ok: true, detail: { copied: files.length, target } };
  }

  /** Apply a set. Without confirm: returns the plan (dry run). */
  async apply(name: string, opts: { confirm?: boolean; autoRollback?: boolean; reason?: string; updateMarker?: boolean } = {}): Promise<Record<string, unknown>> {
    const plan = await this.plan(name);
    if (!opts.confirm || plan.blocked) return { dryRun: true, plan };
    await requireAdmin(this.ops.client);
    return this.lock(async () => {
      const set = this.load(name);
      const snap = await this.snapshot(opts.reason ?? `before-apply-${name}`);
      const steps: StepResult[] = [];
      try {
        await this.applyInner(set, steps);
        const verify = await this.verifyApplied(set);
        steps.push({ step: "verify", ok: verify.ok, detail: verify });
        if (!verify.ok) throw new OpsError("verification after apply failed", steps);
        const health = await this.ops.health(new Date(snap.createdAt));
        steps.push({ step: "health", ok: health.ok, detail: health.ok ? undefined : health.problems });
        if (!health.ok) throw new OpsError(`forum health check failed after apply: ${(health.problems as string[]).join("; ")}`, steps);
        if (opts.updateMarker !== false) this.writeMarker(await this.buildMarker(set, snap.id));
        return { dryRun: false, applied: name, snapshot: snap.id, steps, rollback: `designset rollback ${snap.id}`, logEntry: this.logEntry("apply", name, snap.id, steps) };
      } catch (err) {
        const failure = err as Error;
        if (opts.autoRollback === false) {
          throw new OpsError(`${failure.message}. Forum may be partially changed; restore with: designset rollback ${snap.id}`, steps);
        }
        let rollback: unknown;
        try {
          rollback = await this.rollbackInner(snap);
        } catch (rbErr) {
          throw new OpsError(
            `${failure.message}. AUTOMATIC ROLLBACK ALSO FAILED: ${(rbErr as Error).message}. Run: designset rollback ${snap.id}`,
            steps,
          );
        }
        throw new OpsError(`${failure.message}. The forum was rolled back to snapshot ${snap.id}: ${JSON.stringify((rollback as { verify?: unknown }).verify)}`, steps);
      }
    });
  }

  private async applyInner(set: DesignSet, steps: StepResult[]): Promise<void> {
    const root = this.forumRoot();
    const client = this.ops.client;
    const spec = await this.snapshotKeySpec();
    const current = await this.ops.db.read([...spec.keys, ...Object.keys(set.settings ?? {})], spec.prefixes);
    const forum = (await this.ops.whoami()).forum;
    const planned = await this.plannedSettings(set, current, forum);
    if (planned.issues.some((i) => i.level === "error")) throw new OpsError("set no longer validates", steps);

    steps.push(this.syncStatic(set));

    if ("custom_less" in planned.post) {
      const res = await client.raw({ method: "POST", path: "/settings", body: { custom_less: planned.post.custom_less } });
      steps.push({ step: "custom_less", method: "POST", path: "/api/settings", status: res.status, ok: res.ok, detail: res.ok ? undefined : describeFailure(res) });
      if (!res.ok) throw new OpsError(`custom_less rejected (${res.status}): ${describeFailure(res)}`, steps);
    }
    const rest = Object.fromEntries(Object.entries(planned.post).filter(([k]) => k !== "custom_less"));
    if (Object.keys(rest).length) {
      const res = await client.raw({ method: "POST", path: "/settings", body: rest });
      steps.push({ step: "settings", method: "POST", path: "/api/settings", status: res.status, ok: res.ok, detail: res.ok ? Object.keys(rest) : describeFailure(res) });
      if (!res.ok) throw new OpsError(`settings rejected (${res.status}): ${describeFailure(res)}`, steps);
    }
    if (planned.reset.length) {
      const res = await client.raw({ method: "DELETE", path: "/settings", body: { keys: planned.reset } });
      steps.push({ step: "reset omitted theme keys", method: "DELETE", path: "/api/settings", status: res.status, ok: res.ok, detail: planned.reset });
      if (!res.ok) throw new OpsError(`reset rejected (${res.status}): ${describeFailure(res)}`, steps);
    }

    const marker = this.marker();
    for (const kind of Object.keys(IMAGE_KINDS) as ImageKind[]) {
      const want = set.images?.[kind];
      const spec2 = IMAGE_KINDS[kind];
      const livePath = valueOf(current, spec2.pathKey);
      if (want === undefined) continue;
      if (want === null) {
        if (!livePath) continue;
        const res = await client.raw({ method: "DELETE", path: spec2.route });
        steps.push({ step: `delete ${kind}`, method: "DELETE", path: `/api${spec2.route}`, status: res.status, ok: res.ok });
        if (!res.ok) throw new OpsError(`deleting ${kind} failed (${res.status})`, steps);
        continue;
      }
      const data = readFileSync(join(this.setDir(set.name), want));
      if (marker?.set === set.name && marker.imageHashes?.[kind] === sha256(data) && livePath) continue;
      const { info } = checkUpload(data, want);
      const res = await client.upload({ path: spec2.route, field: spec2.field, filename: `${kind}.${info.ext}`, data, mimeType: info.mime, timeoutMs: 120_000 });
      steps.push({ step: `upload ${kind}`, method: "POST", path: `/api${spec2.route}`, status: res.status, ok: res.ok, detail: res.ok ? undefined : describeFailure(res) });
      if (!res.ok) throw new OpsError(`uploading ${kind} failed (${res.status}): ${describeFailure(res)}`, steps);
    }

    if (set.tags && Object.keys(set.tags).length) {
      const live = await this.readTags();
      for (const [slug, want] of Object.entries(set.tags)) {
        const t = live[slug];
        if (!t) throw new OpsError(`tag "${slug}" does not exist`, steps);
        const attributes: Record<string, unknown> = {};
        for (const f of ["color", "icon", "description"] as const) {
          if (want[f] !== undefined && (t[f] ?? null) !== (want[f] ?? null)) attributes[f] = want[f] ?? null;
        }
        if (!Object.keys(attributes).length) continue;
        const res = await client.raw({ method: "PATCH", path: `/tags/${t.id}`, body: { data: { type: "tags", id: t.id, attributes } } });
        steps.push({ step: `tag ${slug}`, method: "PATCH", path: `/api/tags/${t.id}`, status: res.status, ok: res.ok, detail: res.ok ? attributes : describeFailure(res) });
        if (!res.ok) throw new OpsError(`updating tag ${slug} failed (${res.status}): ${describeFailure(res)}`, steps);
      }
    }

    if (planned.reset.some((k) => CSS_KEYS.includes(k)) || Object.keys(planned.post).some((k) => NEEDS_CACHE_CLEAR_KEYS.includes(k))) {
      const step = await this.ops.cacheClearStep();
      steps.push(step);
      if (!step.ok) throw new OpsError("cache clear failed", steps);
    }
  }

  private async verifyApplied(set: DesignSet): Promise<{ ok: boolean; mismatches: unknown[]; customLessError?: string }> {
    const root = this.forumRoot();
    const spec = await this.snapshotKeySpec();
    const current = await this.ops.db.read([...spec.keys, ...Object.keys(set.settings ?? {}), "custom_less_error"], spec.prefixes);
    const forum = (await this.ops.whoami()).forum;
    const planned = await this.plannedSettings(set, current, forum);
    const mismatches: unknown[] = [
      ...Object.entries(planned.post).map(([k, v]) => ({ key: k, expected: preview(v), actual: summarise(current[k]) })),
      ...planned.reset.map((k) => ({ key: k, expected: "(default)", actual: summarise(current[k]) })),
    ];
    const cle = valueOf(current, "custom_less_error");
    return { ok: mismatches.length === 0 && !cle, mismatches, ...(cle ? { customLessError: cle } : {}) };
  }

  private async buildMarker(set: DesignSet, snapshotId: string): Promise<AppliedMarker> {
    const root = this.forumRoot();
    const current = await this.ops.db.read([...THEME_KEYS]);
    const expected: AppliedMarker["expected"] = {};
    for (const k of THEME_KEYS) {
      const s = current[k];
      expected[k] = !s || s.state === "absent" ? "__default__" : s.state === "value" ? s.value : null;
    }
    const imageHashes: AppliedMarker["imageHashes"] = {};
    for (const [kind, file] of Object.entries(set.images ?? {}) as [ImageKind, string | null][]) {
      if (file) imageHashes[kind] = sha256(readFileSync(join(this.setDir(set.name), file)));
    }
    return { set: set.name, appliedAt: new Date().toISOString(), snapshot: snapshotId, setHash: this.setHash(set.name), expected, imageHashes };
  }

  // -------------------------------------------------------------- rollback

  async rollback(id: string | undefined, opts: { confirm?: boolean } = {}): Promise<Record<string, unknown>> {
    const snap = this.loadSnapshot(id);
    const pending = await this.rollbackPlan(snap);
    if (!opts.confirm) return { dryRun: true, snapshot: snap.id, createdAt: snap.createdAt, reason: snap.reason, ...pending };
    await requireAdmin(this.ops.client);
    return this.lock(async () => {
      const res = await this.rollbackInner(snap);
      if (!(res.verify as { ok: boolean }).ok) throw new OpsError(`rollback finished but verification failed: ${JSON.stringify(res.verify)}`, res.steps as StepResult[]);
      return { dryRun: false, snapshot: snap.id, ...res, logEntry: this.logEntry("rollback", snap.marker?.set ?? "(none)", snap.id, res.steps as StepResult[]) };
    });
  }

  private async liveFor(snap: Snapshot): Promise<SettingsMap> {
    const spec = await this.snapshotKeySpec();
    return this.ops.db.read([...new Set([...snap.settingKeys, ...spec.keys])], spec.prefixes);
  }

  private async rollbackPlan(snap: Snapshot): Promise<{ settings: unknown[]; images: unknown[]; tags: unknown[] }> {
    const live = await this.liveFor(snap);
    const settings: unknown[] = [];
    for (const k of new Set([...Object.keys(snap.settings), ...Object.keys(live)])) {
      if (isVolatile(k) || snap.settings[k]?.state === "redacted" || live[k]?.state === "redacted") continue;
      if (!sameState(snap.settings[k], live[k])) settings.push({ key: k, now: summarise(live[k]), restore: summarise(snap.settings[k]) });
    }
    const images: unknown[] = [];
    for (const kind of Object.keys(IMAGE_KINDS) as ImageKind[]) {
      const livePath = valueOf(live, IMAGE_KINDS[kind].pathKey) ?? null;
      const s = snap.images[kind];
      if ((s?.path ?? null) !== livePath) images.push({ kind, action: s?.file ? "re-upload snapshot copy" : "delete" });
    }
    const tags: unknown[] = [];
    if (Object.keys(snap.tags).length) {
      const liveTags = await this.readTags();
      for (const [slug, t] of Object.entries(snap.tags)) {
        const l = liveTags[slug];
        if (l && (l.color !== t.color || l.icon !== t.icon || l.description !== t.description)) tags.push({ slug, restore: { color: t.color, icon: t.icon, description: t.description } });
      }
    }
    return { settings, images, tags };
  }

  private async rollbackInner(snap: Snapshot): Promise<Record<string, unknown>> {
    const client = this.ops.client;
    const steps: StepResult[] = [];
    const live = await this.liveFor(snap);
    const post: Record<string, string | null> = {};
    const del: string[] = [];
    for (const k of new Set([...Object.keys(snap.settings), ...Object.keys(live)])) {
      if (isVolatile(k)) continue;
      const want = snap.settings[k] ?? { state: "absent" };
      if (want.state === "redacted" || live[k]?.state === "redacted") continue;
      if (sameState(want, live[k])) continue;
      if (want.state === "value") post[k] = want.value;
      else if (want.state === "null") post[k] = null;
      else del.push(k);
    }
    if ("custom_less" in post) {
      const res = await client.raw({ method: "POST", path: "/settings", body: { custom_less: post.custom_less } });
      steps.push({ step: "restore custom_less", method: "POST", path: "/api/settings", status: res.status, ok: res.ok, detail: res.ok ? undefined : describeFailure(res) });
      if (!res.ok) throw new OpsError(`restoring custom_less failed (${res.status}): ${describeFailure(res)}`, steps);
      delete post.custom_less;
    }
    if (Object.keys(post).length) {
      const res = await client.raw({ method: "POST", path: "/settings", body: post });
      steps.push({ step: "restore settings", method: "POST", path: "/api/settings", status: res.status, ok: res.ok, detail: res.ok ? Object.keys(post) : describeFailure(res) });
      if (!res.ok) throw new OpsError(`restoring settings failed (${res.status}): ${describeFailure(res)}`, steps);
    }
    if (del.length) {
      const res = await client.raw({ method: "DELETE", path: "/settings", body: { keys: del } });
      steps.push({ step: "remove keys absent in snapshot", method: "DELETE", path: "/api/settings", status: res.status, ok: res.ok, detail: del });
      if (!res.ok) throw new OpsError(`removing keys failed (${res.status})`, steps);
    }

    const dir = join(this.snapshotsDir, snap.id);
    for (const kind of Object.keys(IMAGE_KINDS) as ImageKind[]) {
      const spec = IMAGE_KINDS[kind];
      const livePath = valueOf(live, spec.pathKey) ?? null;
      const s = snap.images[kind];
      if ((s?.path ?? null) === livePath) continue;
      if (s?.file) {
        const data = readFileSync(join(dir, s.file));
        const { info } = checkUpload(data, s.file);
        const res = await client.upload({ path: spec.route, field: spec.field, filename: `${kind}.${info.ext}`, data, mimeType: info.mime, timeoutMs: 120_000 });
        steps.push({ step: `restore ${kind}`, method: "POST", path: `/api${spec.route}`, status: res.status, ok: res.ok });
        if (!res.ok) throw new OpsError(`restoring ${kind} failed (${res.status}): ${describeFailure(res)}`, steps);
      } else if (livePath) {
        const res = await client.raw({ method: "DELETE", path: spec.route });
        steps.push({ step: `remove ${kind}`, method: "DELETE", path: `/api${spec.route}`, status: res.status, ok: res.ok });
        if (!res.ok) throw new OpsError(`removing ${kind} failed (${res.status})`, steps);
      }
    }

    if (Object.keys(snap.tags).length) {
      const liveTags = await this.readTags();
      for (const [slug, t] of Object.entries(snap.tags)) {
        const l = liveTags[slug];
        if (!l) continue;
        const attributes: Record<string, unknown> = {};
        for (const f of ["color", "icon", "description"] as const) if ((l[f] ?? null) !== (t[f] ?? null)) attributes[f] = t[f] ?? null;
        if (!Object.keys(attributes).length) continue;
        const res = await client.raw({ method: "PATCH", path: `/tags/${l.id}`, body: { data: { type: "tags", id: l.id, attributes } } });
        steps.push({ step: `restore tag ${slug}`, method: "PATCH", path: `/api/tags/${l.id}`, status: res.status, ok: res.ok });
        if (!res.ok) throw new OpsError(`restoring tag ${slug} failed (${res.status})`, steps);
      }
    }

    if (del.some((k) => CSS_KEYS.includes(k) || NEEDS_CACHE_CLEAR_KEYS.includes(k)) || Object.keys(post).some((k) => NEEDS_CACHE_CLEAR_KEYS.includes(k))) {
      const step = await this.ops.cacheClearStep();
      steps.push(step);
      if (!step.ok) throw new OpsError("cache clear failed during rollback", steps);
    }

    // A failed custom_less save leaves custom_less_error behind even though the
    // stored custom_less never changed; Flarum then silently drops custom_less on
    // every compile. Re-saving the (restored) value clears the flag.
    if (await this.ops.customLessError()) {
      const lessNow = valueOf(await this.ops.db.read(["custom_less"]), "custom_less") ?? "";
      const res = await client.raw({ method: "POST", path: "/settings", body: { custom_less: lessNow } });
      steps.push({ step: "clear custom_less_error (re-save custom_less)", method: "POST", path: "/api/settings", status: res.status, ok: res.ok, detail: res.ok ? undefined : describeFailure(res) });
    }

    this.writeMarker(snap.marker);
    const remaining = await this.rollbackPlan(snap);
    const cle = await this.ops.customLessError();
    const verify = {
      ok: remaining.settings.length === 0 && remaining.tags.length === 0 && remaining.images.every((i) => (i as { action: string }).action !== "delete") && !cle,
      remaining,
      ...(cle ? { customLessError: cle } : {}),
      note: "image file names always change on re-upload (Flarum randomises them); only presence is compared",
    };
    return { steps, verify };
  }

  // --------------------------------------------------------------- preview

  async preview(name: string, opts: { confirm?: boolean; viewports?: number[]; pages?: string[] } = {}): Promise<Record<string, unknown>> {
    const plan = await this.plan(name);
    if (!opts.confirm || plan.blocked) return { dryRun: true, plan, note: "preview = snapshot → apply → screenshots → automatic rollback" };
    await requireAdmin(this.ops.client);
    return this.lock(async () => {
      const set = this.load(name);
      const snap = await this.snapshot(`before-preview-${name}`);
      const steps: StepResult[] = [];
      let shots: Record<string, unknown> | undefined;
      let failure: Error | undefined;
      try {
        await this.applyInner(set, steps);
        const verify = await this.verifyApplied(set);
        steps.push({ step: "verify", ok: verify.ok, detail: verify });
        shots = await this.screenshot({ outDir: join(this.setDir(name), "screenshots"), viewports: opts.viewports, pages: opts.pages });
      } catch (e) {
        failure = e as Error;
      }
      const rollback = await this.rollbackInner(snap);
      if (failure) throw new OpsError(`preview failed: ${failure.message}; forum rolled back (${JSON.stringify((rollback as { verify: unknown }).verify)})`, steps);
      return { dryRun: false, previewed: name, snapshot: snap.id, steps, screenshots: shots, rollback: rollback.verify };
    });
  }

  // ------------------------------------------------------------ screenshot

  async screenshot(opts: { outDir: string; viewports?: number[]; pages?: string[]; schemes?: string[] }): Promise<Record<string, unknown>> {
    const forum = (await this.ops.whoami()).forum;
    const scheme = String(forum.colorScheme ?? "auto");
    const schemes = opts.schemes ?? (scheme === "auto" ? ["light", "dark", "light-hc", "dark-hc"] : [scheme]);
    let pages = opts.pages;
    if (!pages) {
      pages = ["/", "/all"];
      try {
        const d = await this.ops.client.request<{ data?: { id: string }[] }>({ path: "/discussions", query: { page: { limit: 1 } } });
        if (d.data?.[0]) pages.push(`/d/${d.data[0].id}`);
      } catch {
        /* no discussions visible */
      }
      if ((await this.ops.enabledExtensions()).includes("flarum-tags")) pages.push("/tags");
    }
    mkdirSync(opts.outDir, { recursive: true });
    const request = { base_url: this.ops.client.forumUrl, pages, schemes, viewports: opts.viewports ?? [1440, 390], out_dir: opts.outDir };
    const python = process.env.FLARUM2_OPS_PYTHON ?? "python3";
    const helper = join(packageRoot(), "helpers", "screenshot.py");
    const result = await new Promise<{ code: number; stdout: string; stderr: string }>((resolveP) => {
      const child = spawn(python, ["-I", helper], { stdio: ["pipe", "pipe", "pipe"] });
      let stdout = "";
      let stderr = "";
      child.stdout.on("data", (d) => (stdout += d));
      child.stderr.on("data", (d) => (stderr += d));
      child.on("error", (e) => resolveP({ code: 127, stdout, stderr: e.message }));
      child.on("close", (code) => resolveP({ code: code ?? 1, stdout, stderr }));
      child.stdin.end(JSON.stringify(request));
    });
    let parsed: Record<string, unknown>;
    try {
      parsed = JSON.parse(result.stdout);
    } catch {
      throw new Error(`screenshot helper failed (exit ${result.code}): ${result.stderr.slice(-800) || result.stdout.slice(-800)}`);
    }
    if (parsed.error) throw new Error(`screenshot helper: ${parsed.error}`);
    return parsed;
  }

  // ------------------------------------------------------------- authoring

  /** Create a new set from the bundled template. */
  create(name: string, title?: string): Record<string, unknown> {
    const dir = this.setDir(name);
    if (existsSync(dir)) throw new Error(`design-set "${name}" already exists`);
    const template = join(packageRoot(), "templates", "design-set");
    cpSync(template, dir, { recursive: true });
    const file = join(dir, "set.json");
    const json = JSON.parse(readFileSync(file, "utf8"));
    json.name = name;
    json.title = title ?? name.replace(/-/g, " ").replace(/\b\w/g, (c: string) => c.toUpperCase());
    writeFileSync(file, JSON.stringify(json, null, 2) + "\n");
    return { created: dir, files: readdirSync(dir) };
  }

  /** Export the live forum design as a new set (settings, LESS/HTML, images, tag styling). */
  async exportLive(name: string, title?: string): Promise<Record<string, unknown>> {
    const dir = this.setDir(name);
    if (existsSync(dir)) throw new Error(`design-set "${name}" already exists`);
    const snap = await this.snapshot(`export-${name}`);
    mkdirSync(join(dir, "images"), { recursive: true });
    const set: DesignSet = { name, title: title ?? `${name} (exported ${snap.createdAt.slice(0, 10)})`, description: `Exported from ${snap.forum} on ${snap.createdAt}`, flarum: "^2.0", settings: {} };
    const ext = await this.ops.enabledExtensions();
    for (const k of [...THEME_KEYS, ...OPTIONAL_DESIGN_KEYS]) {
      const s = snap.settings[k];
      if (!s || s.state !== "value") continue;
      if (k === "custom_less") {
        writeFileSync(join(dir, "custom.less"), s.value);
        set.less = "custom.less";
      } else if (k === "custom_header") {
        writeFileSync(join(dir, "header.html"), s.value);
        set.header = "header.html";
      } else if (k === "custom_footer") {
        writeFileSync(join(dir, "footer.html"), s.value);
        set.footer = "footer.html";
      } else set.settings![k] = s.value;
    }
    void ext;
    const images: NonNullable<DesignSet["images"]> = {};
    for (const [kind, img] of Object.entries(snap.images) as [ImageKind, Snapshot["images"][ImageKind]][]) {
      if (img.file) {
        copyFileSync(join(this.snapshotsDir, snap.id, img.file), join(dir, "images", img.file));
        images[kind] = `images/${img.file}`;
      }
    }
    if (Object.keys(images).length) set.images = images;
    if (Object.keys(snap.tags).length) {
      set.tags = Object.fromEntries(Object.entries(snap.tags).map(([slug, t]) => [slug, { color: t.color, icon: t.icon }]));
    }
    writeFileSync(join(dir, "set.json"), JSON.stringify(set, null, 2) + "\n");
    return { exported: dir, snapshot: snap.id, set };
  }

  // --------------------------------------------------------------- gallery

  gallery(): { file: string; sets: number } {
    const sets = this.list().filter((s) => !s.error);
    const esc = (s: unknown) => String(s ?? "").replace(/[&<>"]/g, (c) => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;" })[c]!);
    const cards = sets
      .map((s) => {
        const shotsDir = join(this.dir, String(s.name), "screenshots");
        const shots = existsSync(shotsDir) ? readdirSync(shotsDir).filter((f) => f.endsWith(".png")).sort() : [];
        const colors = s.colors as { primary?: string; secondary?: string; scheme?: string };
        const imgs = shots
          .map((f) => `<figure><a href="${esc(s.name)}/screenshots/${esc(f)}"><img loading="lazy" src="${esc(s.name)}/screenshots/${esc(f)}" alt="${esc(f)}"></a><figcaption>${esc(f.replace(/\.png$/, ""))}</figcaption></figure>`)
          .join("");
        return `<section class="set"><header><h2>${esc(s.title)} <small>${esc(s.name)}</small>${s.applied ? ' <span class="badge">applied</span>' : ""}</h2><p>${esc(s.description)}</p><p class="sw"><span style="background:${esc(colors.primary ?? "#4D698E")}"></span><span style="background:${esc(colors.secondary ?? "#4D698E")}"></span> scheme: ${esc(colors.scheme ?? "default")}</p><code>flarum2-ops designset preview ${esc(s.name)} --confirm</code></header><div class="shots">${imgs || "<p><em>No screenshots yet: run preview.</em></p>"}</div></section>`;
      })
      .join("\n");
    const html = `<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Design-set gallery</title><style>
:root{--bg:#f6f7f9;--fg:#1d2330;--card:#fff;--muted:#5d6675;--line:#dde1e7}
@media (prefers-color-scheme:dark){:root{--bg:#14171c;--fg:#e8ebf0;--card:#1d2128;--muted:#9aa3b2;--line:#2c323c}}
body{margin:0;padding:24px 16px;background:var(--bg);color:var(--fg);font:15px/1.5 system-ui,sans-serif}
h1{margin:0 0 16px}.set{background:var(--card);border:1px solid var(--line);border-radius:10px;padding:16px;margin:0 0 20px}
h2{margin:0;font-size:20px}small{color:var(--muted);font-weight:400}.badge{background:#1a7f45;color:#fff;border-radius:999px;padding:2px 8px;font-size:12px}
.sw span{display:inline-block;width:18px;height:18px;border-radius:4px;vertical-align:middle;margin-right:4px;border:1px solid var(--line)}
code{font-size:12px;color:var(--muted)}.shots{display:grid;grid-template-columns:repeat(auto-fill,minmax(220px,1fr));gap:12px;margin-top:12px}
figure{margin:0}img{width:100%;height:160px;object-fit:cover;object-position:top;border:1px solid var(--line);border-radius:6px}figcaption{font-size:12px;color:var(--muted)}
</style></head><body><h1>Design-set gallery</h1><p>Generated ${esc(new Date().toISOString())} · ${sets.length} set(s)</p>${cards}</body></html>\n`;
    const file = join(this.dir, "gallery.html");
    writeFileSync(file, html);
    return { file, sets: sets.length };
  }

  // ---------------------------------------------------------------- doctor

  async doctor(): Promise<Record<string, unknown>> {
    const cfg = this.ops.cfg;
    const out: Record<string, unknown> = {
      config: { name: cfg.name, baseUrl: cfg.baseUrl, forumRoot: cfg.forumRoot, designSetsDir: cfg.designSetsDir, source: cfg.source },
      mode: this.ops.client.readOnly ? "read-only" : "write (every write needs confirm)",
    };
    const problems: string[] = [];
    try {
      const { actor } = await this.ops.whoami();
      out.actor = actor;
      if (!this.ops.client.hasCredentials) problems.push("no token: run `flarum2-ops login` (needed for any write)");
      else if (!actor.authenticated) problems.push("token rejected: requests run as guest; run `flarum2-ops login` again");
      else if (!actor.isAdmin) problems.push(`token user ${actor.username} is not an admin`);
    } catch (e) {
      problems.push(`forum API unreachable: ${(e as Error).message}`);
    }
    const health = await this.ops.health();
    out.health = health;
    problems.push(...((health.problems as string[]) ?? []));
    if (this.ops.local) {
      out.enabledExtensions = await this.ops.enabledExtensions();
      const marker = this.marker();
      out.applied = marker ? { set: marker.set, at: marker.appliedAt, snapshot: marker.snapshot } : null;
      if (marker) {
        const now = await this.ops.db.read([...THEME_KEYS]);
        const drift = THEME_KEYS.filter((k) => {
          const want = marker.expected[k];
          const s = now[k];
          const got = !s || s.state === "absent" ? "__default__" : s.state === "value" ? s.value : null;
          return want !== got;
        });
        if (drift.length) {
          out.drift = drift;
          problems.push(`live design differs from applied set "${marker.set}" in: ${drift.join(", ")} (changed in the admin UI?); export it or re-apply`);
        }
        if (existsSync(this.setDir(marker.set)) && this.setHash(marker.set) !== marker.setHash) {
          out.setChangedSinceApply = true;
        }
      }
      out.snapshots = this.listSnapshots().length;
    }
    if (existsSync(this.lockFile)) out.lock = readFileSync(this.lockFile, "utf8").trim();
    out.sets = this.list().map((s) => s.name);
    out.problems = problems;
    out.ok = problems.length === 0;
    return out;
  }

  // ----------------------------------------------------------------- misc

  logEntry(action: string, set: string, snapshot: string, steps: StepResult[]): string {
    const ts = new Date();
    const pad = (n: number) => String(n).padStart(2, "0");
    const when = `${ts.getFullYear()}-${pad(ts.getMonth() + 1)}-${pad(ts.getDate())} ${pad(ts.getHours())}:${pad(ts.getMinutes())}`;
    const calls = steps.filter((s) => s.method).map((s) => `${s.method} ${s.path} → ${s.status}`);
    return [
      `### ${when} — design-set ${action}: ${set}`,
      "- Agent: flarum2-ops",
      "- Scope: api",
      `- Changed files: public/assets/${this.ops.cfg.publicAssetsSubdir}/${set}/ (static copies, if any)`,
      `- Commands: flarum2-ops designset ${action} ${action === "rollback" ? snapshot : set} --confirm (${calls.length} API calls: ${calls.join("; ") || "none"})`,
      "- Verification: settings read back + custom_less_error clear + health check (root/API/CSS 200, services, logs)",
      `- Backup/rollback: snapshot ${snapshot} → flarum2-ops designset rollback ${snapshot} --confirm`,
      "- Notes:",
    ].join("\n");
  }
}

export { basename };
